ALTER TABLE public.financeiro ADD COLUMN previsao boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION private.freight_city_rules(_rules jsonb,_city text,_uf text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE ops jsonb; op jsonb; replace_count int:=0; replacement numeric; BEGIN SELECT coalesce(jsonb_agg(value-'cidade'-'uf'),'[]') INTO ops FROM jsonb_array_elements(coalesce(_rules->'operacoes','[]')) WHERE coalesce(value->>'habilitado','true')<>'false' AND (nullif(value->>'cidade','') IS NULL OR lower(trim(value->>'cidade'))=lower(trim(_city))) AND (nullif(value->>'uf','') IS NULL OR upper(trim(value->>'uf'))=upper(trim(_uf))); FOR op IN SELECT value FROM jsonb_array_elements(ops) WHERE value->>'substitui_base'='true' LOOP IF op->>'tipo'<>'fixo' OR (op->>'valor')::numeric<=0 THEN RAISE EXCEPTION 'Substituição requer tarifa fixa positiva'; END IF; replace_count:=replace_count+1; replacement:=(op->>'valor')::numeric; END LOOP; IF replace_count>1 THEN RAISE EXCEPTION 'Mais de uma tarifa substitui a base nesta cidade'; END IF; IF replace_count=1 THEN _rules:=_rules||jsonb_build_object('metodo','fixo','tarifa',replacement); END IF; SELECT coalesce(jsonb_agg(value),'[]') INTO ops FROM jsonb_array_elements(ops) WHERE coalesce(value->>'substitui_base','false')<>'true'; RETURN jsonb_set(_rules,'{operacoes}',ops); END $$;
REVOKE ALL ON FUNCTION private.freight_city_rules(jsonb,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.simular_frete_cidade(_regras jsonb,_cidade uuid,_peso numeric,_valor numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d distancias; result jsonb; BEGIN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO d FROM distancias WHERE id=_cidade; IF NOT FOUND THEN RETURN jsonb_build_object('situacao','aguardando_distancia','total',NULL,'erro','Selecione uma cidade com distância cadastrada'); END IF; result:=public.simular_frete(private.freight_city_rules(_regras,d.cidade,d.uf),_peso,_valor,d.km); RETURN result||jsonb_build_object('destino',d.cidade||' / '||d.uf,'distancia',d.km,'origem','Teresina / PI'); END $$;
REVOKE ALL ON FUNCTION public.simular_frete_cidade(jsonb,uuid,numeric,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.simular_frete_cidade(jsonb,uuid,numeric,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION private.prepare_freight(_nota uuid,_motivo text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n notas_fiscais; f uuid; t tabelas_frete; km numeric; mem jsonb; calc uuid; st text; regras jsonb; candidates int; city text; destination_uf text; peso numeric; billed boolean; BEGIN SELECT * INTO n FROM notas_fiscais WHERE id=_nota FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Nota não encontrada'; END IF; IF EXISTS(SELECT 1 FROM financeiro WHERE nota_fiscal_id=_nota AND estado_frete IN ('conferido','pronto_faturamento','faturado')) THEN RAISE EXCEPTION 'Frete fechado: recálculo bloqueado'; END IF; SELECT id INTO f FROM fornecedores WHERE cnpj=regexp_replace(coalesce(n.cnpj_emissor,''),'\D','','g'); city:=coalesce(nullif(n.destino_entrega_cidade,''),n.cidade);destination_uf:=coalesce(nullif(n.destino_entrega_uf,''),n.uf);peso:=coalesce(n.peso_frete,n.peso); IF n.tabela_frete_id IS NOT NULL THEN SELECT * INTO t FROM tabelas_frete WHERE id=n.tabela_frete_id AND fornecedor_id=f AND ativo AND inicio<=coalesce(n.data_emissao,current_date) AND (fim IS NULL OR fim>=coalesce(n.data_emissao,current_date)); ELSE SELECT count(*) INTO candidates FROM (SELECT DISTINCT ON (nome) * FROM tabelas_frete WHERE fornecedor_id=f AND inicio<=coalesce(n.data_emissao,current_date) AND (fim IS NULL OR fim>=coalesce(n.data_emissao,current_date)) ORDER BY nome,versao DESC,created_at DESC) x WHERE ativo; IF candidates=1 THEN SELECT x.* INTO t FROM (SELECT DISTINCT ON (nome) * FROM tabelas_frete WHERE fornecedor_id=f AND inicio<=coalesce(n.data_emissao,current_date) AND (fim IS NULL OR fim>=coalesce(n.data_emissao,current_date)) ORDER BY nome,versao DESC,created_at DESC) x WHERE ativo LIMIT 1; END IF; END IF; SELECT d.km INTO km FROM distancias d WHERE lower(trim(d.cidade))=lower(trim(city)) AND upper(d.uf)=upper(destination_uf) ORDER BY atualizado_em DESC LIMIT 1; IF t.id IS NULL THEN st:=CASE WHEN candidates>1 THEN 'calculo_pendente' ELSE 'sem_tabela' END;mem:=jsonb_build_object('situacao',st,'total',NULL,'erro',CASE WHEN candidates>1 THEN 'Selecione o contrato aplicável' ELSE 'Sem tabela ativa aplicável' END); ELSE regras:=private.freight_city_rules(t.regras,city,destination_uf); mem:=public.simular_frete(regras,peso,n.valor,km);st:=mem->>'situacao'; END IF; mem:=mem||jsonb_build_object('peso',peso,'valor_nf',n.valor,'origem','Teresina / PI','destino',city||' / '||coalesce(destination_uf,''),'fornecedor',n.fornecedor,'tabela',t.nome,'versao',t.versao,'data_referencia',coalesce(n.data_emissao,current_date),'distancia',km,'regras_aplicadas',regras); INSERT INTO calculos_frete(nota_id,tabela_id,situacao,total,memoria,motivo) VALUES(_nota,t.id,st,(mem->>'total')::numeric,mem,_motivo) RETURNING id INTO calc; billed:=EXISTS(SELECT 1 FROM comprovantes WHERE nota_id=_nota AND status='aprovado' AND tipo_documento='canhoto'); INSERT INTO financeiro(nota_fiscal_id,fornecedor_id,previsao,estado_frete) VALUES(_nota,f,NOT billed,st) ON CONFLICT(nota_fiscal_id) DO NOTHING; UPDATE financeiro SET fornecedor_id=f,previsao=NOT billed,calculo_id=calc,estado_frete=CASE WHEN st='pre_calculado' AND billed THEN 'aguardando_conferencia' ELSE st END,valor_base=coalesce((mem->>'base')::numeric,0),valor_ad_valorem=coalesce((mem->>'ad_valorem')::numeric,0),valor_tributos=coalesce((mem->>'tributos')::numeric,0),valor_taxa_extra=coalesce((mem->>'adicionais')::numeric,0),valor_frete=coalesce((mem->>'total')::numeric,0),distancia=km WHERE nota_fiscal_id=_nota; RETURN calc; END $$;
REVOKE ALL ON FUNCTION private.prepare_freight(uuid,text) FROM PUBLIC,anon,authenticated;
INSERT INTO public.financeiro(nota_fiscal_id,fornecedor_id,calculo_id,previsao,estado_frete,valor_base,valor_ad_valorem,valor_tributos,valor_taxa_extra,valor_frete,distancia) SELECT n.id,f.id,c.id,true,coalesce(c.situacao,'calculo_pendente'),coalesce((c.memoria->>'base')::numeric,0),coalesce((c.memoria->>'ad_valorem')::numeric,0),coalesce((c.memoria->>'tributos')::numeric,0),coalesce((c.memoria->>'adicionais')::numeric,0),coalesce(c.total,0),(c.memoria->>'distancia')::numeric FROM public.notas_fiscais n LEFT JOIN public.fornecedores f ON f.cnpj=regexp_replace(coalesce(n.cnpj_emissor,''),'\D','','g') LEFT JOIN LATERAL(SELECT * FROM public.calculos_frete WHERE nota_id=n.id ORDER BY created_at DESC LIMIT 1) c ON true WHERE NOT EXISTS(SELECT 1 FROM public.financeiro WHERE nota_fiscal_id=n.id) ON CONFLICT(nota_fiscal_id) DO NOTHING;